CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS scans(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID REFERENCES users(id) ON DELETE CASCADE,type TEXT NOT NULL,input TEXT NOT NULL,risk_score INT NOT NULL,classification TEXT NOT NULL,threat_category TEXT NOT NULL,confidence INT NOT NULL,analysis JSONB NOT NULL,recommendations JSONB NOT NULL,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS risk_factors(id SERIAL PRIMARY KEY,scan_id UUID REFERENCES scans(id) ON DELETE CASCADE,name TEXT,weight INT,score INT);
CREATE TABLE IF NOT EXISTS notifications(id SERIAL PRIMARY KEY,user_id UUID REFERENCES users(id) ON DELETE CASCADE,message TEXT,read BOOLEAN DEFAULT false,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS user_settings(user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,theme TEXT DEFAULT 'dark',notifications BOOLEAN DEFAULT true);
CREATE TABLE IF NOT EXISTS password_reset_tokens(token_hash TEXT PRIMARY KEY,user_id UUID REFERENCES users(id) ON DELETE CASCADE,expires_at TIMESTAMPTZ NOT NULL);
